const r = await tools.exec_command({cmd:"python3 - <<'PY'
import re,glob,os
files=glob.glob('store/*.go')
types=[]
for f in files:
 s=open(f).read()
 for m in re.finditer(r'^type (\w+) struct',s,re.M): types.append(m.group(1))
for t in types:
 pk=set(); refs=[]
 for f in glob.glob('**/*.go',recursive=True):
  if f.startswith('store/'): continue
  s=open(f,errors='ignore').read()
  if re.search(r'\bstore\.'+t+r'\b',s): pk.add(os.path.dirname(f)); refs.append(f)
 print(t,len(pk),sorted(pk))
PY","workdir":"/bench/repo"}); text(r.output);

